import React, { useState, useEffect } from 'react';
import { Part, Tool, ManualPunchMode, SnapMode, NibbleSettings, DestructSettings, Point, PlacedTool, PlacementReference, PlacementSide, TurretLayout, TeachCycle } from '../types';
import { useManualPunch } from '../hooks/useManualPunch';
import { usePanAndZoom } from '../hooks/usePanAndZoom';
import { getGeometryFromEntities, findClosestSegment } from '../services/geometry';
import { generateContourPunches } from '../services/punching';
import { createTeachCycleFromSelection } from '../services/teachLogic';
import { generateId, getPartBaseName, generatePartNameFromProfile } from '../utils/helpers';
import { MainLayout } from '../components/MainLayout';
import { PartEditorSidebar } from '../components/sidebar/PartEditorSidebar';
import { PartEditorCanvas } from '../components/canvas/PartEditorCanvas';
import { AutoPunchSettingsModal } from '../components/AutoPunchSettingsModal';
import { TeachCycleSaveModal } from '../components/TeachCycleSaveModal';
import { ActionButton } from '../components/common/Button';
import { SettingsIcon } from '../components/Icons';

interface PartEditorViewProps {
    activePart: Part | null;
    setActivePart: (part: Part | null) => void;
    tools: Tool[];
    parts: Part[];
    setParts: (parts: Part[] | ((prev: Part[]) => Part[])) => void;
    scripts: any[];
    setScripts: (scripts: any[] | ((prev: any[]) => any[])) => void;
    turretLayouts: TurretLayout[];
    teachCycles: TeachCycle[];
    setTeachCycles: (cycles: TeachCycle[] | ((prev: TeachCycle[]) => TeachCycle[])) => void;
    addToast: (msg: string, type: 'success' | 'error' | 'info') => void;
    confirm: (title: string, message: string, onAction: () => void) => void;
}

export const PartEditorView: React.FC<PartEditorViewProps> = ({
    activePart, setActivePart, tools, parts, setParts, scripts, setScripts, turretLayouts, teachCycles, setTeachCycles, addToast, confirm
}) => {
    // Internal UI State
    const [manualPunchMode, setManualPunchMode] = useState<ManualPunchMode>(ManualPunchMode.Punch);
    const [selectedToolId, setSelectedToolId] = useState<string | null>(null);
    const [selectedPunchId, setSelectedPunchId] = useState<string | null>(null);
    const [punchOrientation, setPunchOrientation] = useState(0);
    const [snapMode, setSnapMode] = useState<SnapMode>(SnapMode.Vertex);
    const [punchOffset, setPunchOffset] = useState<number>(0);
    const [nibbleSettings, setNibbleSettings] = useState<NibbleSettings>({ extensionStart: 0, extensionEnd: 0, minOverlap: 1, hitPointMode: 'offset', toolPosition: 'long' });
    const [destructSettings, setDestructSettings] = useState<DestructSettings>({ overlap: 0.7, scallop: 0.25, notchExpansion: 0.25 });

    // Teach Mode State
    const [teachMode, setTeachMode] = useState(false);
    const [selectedSegmentIds, setSelectedSegmentIds] = useState<number[]>([]);
    const [selectedTeachPunchIds, setSelectedTeachPunchIds] = useState<string[]>([]);

    // Modals
    const [showAutoPunchModal, setShowAutoPunchModal] = useState(false);
    const [showTeachSaveModal, setShowTeachSaveModal] = useState(false);

    const activePartProcessedGeometry = React.useMemo(() => activePart ? getGeometryFromEntities(activePart) : null, [activePart]);
    const selectedTool = tools.find(t => t.id === selectedToolId) || null;

    const handleCanvasClick = (rawPoint: Point) => {
        if (!activePart) return;
        const point = { x: rawPoint.x, y: -rawPoint.y };

        if (teachMode) {
             const closestSeg = findClosestSegment(point, activePartProcessedGeometry);
             if (closestSeg) {
                 const idx = activePartProcessedGeometry?.segments.findIndex(s => 
                     Math.abs(s.p1.x - closestSeg.p1.x) < 0.001 && Math.abs(s.p1.y - closestSeg.p1.y) < 0.001 &&
                     Math.abs(s.p2.x - closestSeg.p2.x) < 0.001 && Math.abs(s.p2.y - closestSeg.p2.y) < 0.001
                 ) ?? -1;
                 if (idx !== -1) {
                     setSelectedSegmentIds(prev => prev.includes(idx) ? prev.filter(i => i !== idx) : [...prev, idx]);
                 }
             }
             return;
        }

        handleManualPunchClick(rawPoint);
    };

    const { svgRef, viewBox, setViewBox, isDragging, getPointFromEvent, panZoomHandlers } = usePanAndZoom(
        { x: -5, y: -505, width: 1010, height: 1010 }, 
        { onClick: handleCanvasClick }
    );

    const { handleCanvasClick: handleManualPunchClick, punchCreationStep, punchCreationPoints } = useManualPunch({
        activePart, activePartProcessedGeometry, selectedTool, manualPunchMode, punchOrientation, punchOffset, snapMode, nibbleSettings, destructSettings,
        onAddPunches: (newPunches) => {
            if (!activePart) return;
            const punchesWithIds = newPunches.map(p => ({ ...p, id: generateId() }));
            setActivePart({ ...activePart, punches: [...activePart.punches, ...punchesWithIds] });
        },
        setSelectedPunchId
    });

    const handleTeachBulkSelect = (segmentIndices: number[], punchIds: string[], add: boolean) => {
        if (add) {
            setSelectedSegmentIds(prev => Array.from(new Set([...prev, ...segmentIndices])));
            setSelectedTeachPunchIds(prev => Array.from(new Set([...prev, ...punchIds])));
        } else {
            setSelectedSegmentIds(segmentIndices);
            setSelectedTeachPunchIds(punchIds);
        }
    };

    const handleSaveTeachCycle = (name: string, symmetry: any) => {
        if (!activePart || !activePartProcessedGeometry) return;
        const newCycle = createTeachCycleFromSelection(name, symmetry, selectedSegmentIds, selectedTeachPunchIds, activePart, activePartProcessedGeometry);
        if (newCycle) {
            setTeachCycles(prev => [...prev, newCycle]);
            setTeachMode(false);
            addToast("Цикл обучения сохранен", "success");
        }
        setShowTeachSaveModal(false);
    };

    const handleUpdateActivePart = (updates: Partial<Part>) => {
        if (activePart) setActivePart({ ...activePart, ...updates });
    };

    return (
        <MainLayout
            sidebar={
                <PartEditorSidebar 
                    activePart={activePart}
                    parts={parts}
                    tools={tools}
                    onFileUpload={() => {}} // Handled by App.tsx through Input in sidebar usually, but here specialized
                    manualPunchMode={manualPunchMode}
                    setManualPunchMode={setManualPunchMode}
                    selectedToolId={selectedToolId}
                    setSelectedToolId={setSelectedToolId}
                    selectedPunchId={selectedPunchId}
                    setSelectedPunchId={setSelectedPunchId}
                    onDeletePunch={(ids) => {
                        const idList = Array.isArray(ids) ? ids : [ids];
                        if (activePart) setActivePart({ ...activePart, punches: activePart.punches.filter(p => !idList.includes(p.id)) });
                    }}
                    onUpdatePunch={(id, u) => {
                        if (activePart) setActivePart({ ...activePart, punches: activePart.punches.map(p => p.id === id ? { ...p, ...u } : p) });
                    }}
                    onClearAllPunches={() => confirm("Очистка", "Удалить все удары?", () => setActivePart(activePart ? { ...activePart, punches: [] } : null))}
                    punchOrientation={punchOrientation}
                    setPunchOrientation={setPunchOrientation}
                    onCyclePunchOrientation={() => setPunchOrientation((punchOrientation + 90) % 360)}
                    snapMode={snapMode}
                    setSnapMode={setSnapMode}
                    punchOffset={punchOffset}
                    setPunchOffset={setPunchOffset}
                    nibbleSettings={nibbleSettings}
                    setNibbleSettings={setNibbleSettings}
                    destructSettings={destructSettings}
                    setDestructSettings={setDestructSettings}
                    onSavePartAsScript={() => {}} // App logic
                    onSavePartAsStatic={() => {}} // App logic
                    onUpdateActivePart={handleUpdateActivePart}
                    onClosePart={() => setActivePart(null)}
                    teachMode={teachMode}
                    setTeachMode={(val) => { setTeachMode(val); if (val) { setSelectedSegmentIds([]); setSelectedTeachPunchIds([]); } }}
                    onSaveTeachCycle={() => setShowTeachSaveModal(true)}
                    teachCycles={teachCycles}
                    onDeleteTeachCycle={(id) => setTeachCycles(prev => prev.filter(c => c.id !== id))}
                />
            }
        >
            <div className="flex flex-col h-full">
                <div className="flex-none bg-gray-700/50 p-2 flex items-center space-x-4">
                     <ActionButton icon={<SettingsIcon />} label="Авто-расстановка" onClick={() => setShowAutoPunchModal(true)} disabled={!activePart}/>
                </div>
                <div className="flex-1 bg-gray-900 relative overflow-hidden">
                    <svg 
                        ref={svgRef}
                        width="100%" height="100%" 
                        viewBox={`${viewBox.x} ${viewBox.y} ${viewBox.width} ${viewBox.height}`}
                        {...panZoomHandlers}
                        className="cursor-crosshair"
                    >
                        <g transform="scale(1, -1)">
                            {activePart && (
                                <PartEditorCanvas 
                                    activePart={activePart}
                                    processedGeometry={activePartProcessedGeometry}
                                    tools={tools}
                                    mousePos={getPointFromEvent({ clientX: 0, clientY: 0 } as any)} // Placeholder, hook handles it better
                                    manualPunchMode={manualPunchMode}
                                    punchCreationStep={punchCreationStep}
                                    punchCreationPoints={punchCreationPoints}
                                    selectedToolId={selectedToolId}
                                    selectedPunchId={selectedPunchId}
                                    placementReference={PlacementReference.Edge}
                                    placementSide={PlacementSide.Outside}
                                    punchOrientation={punchOrientation}
                                    snapMode={snapMode}
                                    punchOffset={punchOffset}
                                    nibbleSettings={nibbleSettings}
                                    teachMode={teachMode}
                                    selectedSegmentIds={selectedSegmentIds}
                                    selectedTeachPunchIds={selectedTeachPunchIds}
                                    onTeachBulkSelect={handleTeachBulkSelect}
                                    onSelectPunch={setSelectedPunchId}
                                />
                            )}
                        </g>
                    </svg>
                </div>
            </div>

            {showAutoPunchModal && activePart && (
                <AutoPunchSettingsModal 
                    onClose={() => setShowAutoPunchModal(false)}
                    onApply={(s) => {
                        const p = generateContourPunches(activePart.geometry, tools, s, turretLayouts, teachCycles);
                        setActivePart({ ...activePart, punches: [...activePart.punches, ...p.map(x => ({ ...x, id: generateId() }))] });
                        setShowAutoPunchModal(false);
                    }}
                    turretLayouts={turretLayouts}
                />
            )}
            {showTeachSaveModal && <TeachCycleSaveModal onClose={() => setShowTeachSaveModal(false)} onSave={handleSaveTeachCycle} />}
        </MainLayout>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { NestLayout, Part, Tool, OptimizerSettings, MachineSettings, PunchOp, ScheduledPart } from '../types';
import { nestingGenerator } from '../services/nesting';
import { calculateOptimizedPath } from '../services/gcode';
import { MainLayout } from '../components/MainLayout';
import { NestingSidebarPanel } from '../components/sidebar/NestingSidebarPanel';
import { NestingCanvas } from '../components/canvas/NestingCanvas';
import { RightPanel } from '../components/RightPanel';
import { usePanAndZoom } from '../hooks/usePanAndZoom';

interface NestingViewProps {
    activeNestId: string | null;
    nests: NestLayout[];
    setNests: (nests: NestLayout[] | ((prev: NestLayout[]) => NestLayout[])) => void;
    parts: Part[];
    tools: Tool[];
    machineSettings: MachineSettings;
    optimizerSettings: OptimizerSettings;
    setOptimizerSettings: (s: OptimizerSettings) => void;
    addToast: (msg: string, type: any) => void;
    confirm: (title: string, message: string, onAction: () => void) => void;
    onOpenOptimizer: (forGCode: boolean) => void;
}

export const NestingView: React.FC<NestingViewProps> = ({
    activeNestId, nests, setNests, parts, tools, machineSettings, optimizerSettings, setOptimizerSettings, addToast, confirm, onOpenOptimizer
}) => {
    const [activeSheetIndex, setActiveSheetIndex] = useState(0);
    const [selectedNestPartId, setSelectedNestPartId] = useState<string | null>(null);
    const [optimizedOperations, setOptimizedOperations] = useState<PunchOp[] | null>(null);
    const [simulationStep, setSimulationStep] = useState(0);
    const [isSimulating, setIsSimulating] = useState(false);
    const [simulationSpeed, setSimulationSpeed] = useState(50);
    const [isProcessing, setIsProcessing] = useState(false);
    const [progress, setProgress] = useState(0);

    const activeNest = nests.find(n => n.id === activeNestId) || null;
    const currentSheet = activeNest?.sheets[activeSheetIndex] || null;

    const { svgRef, viewBox, setViewBox, panZoomHandlers } = usePanAndZoom(
        { x: -50, y: -1300, width: 2700, height: 1400 }
    );

    useEffect(() => {
        if (currentSheet) {
            setOptimizedOperations(calculateOptimizedPath(currentSheet, parts, tools, optimizerSettings));
            setSimulationStep(0);
        }
    }, [currentSheet?.id, optimizerSettings]);

    const handleRunNesting = async () => {
        if (!activeNest) return;
        setIsProcessing(true);
        try {
            for await (const update of nestingGenerator(activeNest.scheduledParts, parts, tools, activeNest.settings)) {
                setNests(prev => prev.map(n => n.id === activeNestId ? { ...n, sheets: update.sheets } : n));
                setProgress(update.progress);
            }
            addToast("Раскрой завершен", "success");
        } catch (e) {
            addToast("Ошибка раскроя", "error");
        } finally {
            setIsProcessing(false);
        }
    };

    const handleUpdateSettings = (s: any, sp: ScheduledPart[]) => {
        setNests(prev => prev.map(n => n.id === activeNestId ? { ...n, settings: s, scheduledParts: sp } : n));
    };

    return (
        <MainLayout
            sidebar={
                activeNest && (
                    <div className="flex flex-col h-full space-y-4">
                        <NestingSidebarPanel 
                            activeNest={activeNest} 
                            allParts={parts} 
                            onSettingsChange={handleUpdateSettings}
                            onMetadataChange={(m) => setNests(prev => prev.map(n => n.id === activeNestId ? { ...n, ...m } : n))}
                        />
                        <button 
                            onClick={handleRunNesting}
                            className="w-full bg-blue-600 hover:bg-blue-700 text-white p-3 rounded font-bold"
                            disabled={isProcessing}
                        >
                            {isProcessing ? `Выполнение ${Math.round(progress)}%` : "Выполнить раскрой"}
                        </button>
                    </div>
                )
            }
        >
            <div className="flex h-full overflow-hidden">
                <div className="flex-1 bg-gray-900">
                    <svg 
                        ref={svgRef}
                        width="100%" height="100%" 
                        viewBox={`${viewBox.x} ${viewBox.y} ${viewBox.width} ${viewBox.height}`}
                        {...panZoomHandlers}
                    >
                        <g transform="scale(1, -1)">
                            <NestingCanvas 
                                activeNest={activeNest!}
                                currentNestSheet={currentSheet}
                                parts={parts}
                                tools={tools}
                                selectedNestPartId={selectedNestPartId}
                                optimizedOperations={optimizedOperations}
                                simulationStep={simulationStep}
                            />
                        </g>
                    </svg>
                </div>
                <RightPanel 
                    tools={tools}
                    selectedToolId={null}
                    setSelectedToolId={() => {}}
                    onOpenTurretView={() => {}}
                    isNestingMode={true}
                    activeNest={activeNest}
                    activeSheetIndex={activeSheetIndex}
                    setActiveSheetIndex={setActiveSheetIndex}
                    allParts={parts}
                    simulationStep={simulationStep}
                    totalSimulationSteps={optimizedOperations?.length || 0}
                    isSimulating={isSimulating}
                    simulationSpeed={simulationSpeed}
                    onToggleSimulation={() => setIsSimulating(!isSimulating)}
                    onStopSimulation={() => { setIsSimulating(false); setSimulationStep(0); }}
                    onStepChange={setSimulationStep}
                    onSpeedChange={setSimulationSpeed}
                    optimizedOperations={optimizedOperations}
                />
            </div>
        </MainLayout>
    );
};

import React, { useState } from 'react';
import { AppMode, NestLayout, Part, Tool, TurretLayout, ParametricScript, MachineSettings, OptimizerSettings, ToastMessage } from './types';
import { initialTools, initialParts, initialNests, initialTurretLayouts, initialScripts, defaultMachineSettings, defaultOptimizerSettings } from './data/initialData';
import { generateId } from './utils/helpers';
import { useLocalStorage } from './hooks/useLocalStorage';
import { useConfirmation } from './hooks/useConfirmation';

import { Header } from './components/Header';
import { ToolLibraryView } from './components/ToolLibraryView';
import { TurretSetupView } from './components/TurretSetupView';
import { ScriptLibraryView } from './components/ScriptLibraryView';
import { PartLibraryView } from './components/PartLibraryView';
import { MachineSetupView } from './components/MachineSetupView';
import { ConfirmationModal } from './components/common/ConfirmationModal';
import { ToastContainer } from './components/common/Toast';

import { PartEditorView } from './views/PartEditorView';
import { NestingView } from './views/NestingView';

const App: React.FC = () => {
    const [mode, setMode] = useState<AppMode>(AppMode.PartEditor);

    // --- Global Persistent State ---
    const [tools, setTools] = useLocalStorage<Tool[]>('fp_tools', initialTools);
    const [parts, setParts] = useLocalStorage<Part[]>('fp_parts', initialParts);
    const [scripts, setScripts] = useLocalStorage<ParametricScript[]>('fp_scripts', initialScripts);
    const [nests, setNests] = useLocalStorage<NestLayout[]>('fp_nests', initialNests);
    const [turretLayouts, setTurretLayouts] = useLocalStorage<TurretLayout[]>('fp_turret_layouts', initialTurretLayouts);
    const [machineSettings, setMachineSettings] = useLocalStorage<MachineSettings>('fp_machine_settings', defaultMachineSettings);
    const [optimizerSettings, setOptimizerSettings] = useLocalStorage<OptimizerSettings>('fp_optimizer_settings', defaultOptimizerSettings);
    const [teachCycles, setTeachCycles] = useLocalStorage<any[]>('fp_teach_cycles', []);

    // --- Session Global State ---
    const [activePart, setActivePart] = useState<Part | null>(null);
    const [activeNestId, setActiveNestId] = useState<string | null>(nests[0]?.id || null);
    const [toasts, setToasts] = useState<ToastMessage[]>([]);

    const { confirmationState, confirm, closeConfirmation } = useConfirmation();

    const addToast = (message: string, type: ToastMessage['type']) => {
        setToasts(prev => [...prev, { id: generateId(), message, type }]);
    };
    const removeToast = (id: string) => setToasts(prev => prev.filter(t => t.id !== id));

    const renderModeContent = () => {
        switch (mode) {
            case AppMode.PartEditor:
                return (
                    <PartEditorView 
                        activePart={activePart}
                        setActivePart={setActivePart}
                        tools={tools}
                        parts={parts}
                        setParts={setParts}
                        scripts={scripts}
                        setScripts={setScripts}
                        turretLayouts={turretLayouts}
                        teachCycles={teachCycles}
                        setTeachCycles={setTeachCycles}
                        addToast={addToast}
                        confirm={confirm}
                    />
                );
            case AppMode.Nesting:
                return (
                    <NestingView 
                        activeNestId={activeNestId}
                        nests={nests}
                        setNests={setNests}
                        parts={parts}
                        tools={tools}
                        machineSettings={machineSettings}
                        optimizerSettings={optimizerSettings}
                        setOptimizerSettings={setOptimizerSettings}
                        addToast={addToast}
                        confirm={confirm}
                        onOpenOptimizer={() => {}} // To be connected
                    />
                );
            case AppMode.PartLibrary:
                return (
                    <PartLibraryView 
                        parts={parts} tools={tools}
                        onLoadPart={(p) => { setActivePart(p); setMode(AppMode.PartEditor); }}
                        onDeletePart={(id) => confirm("Удаление", "Удалить?", () => setParts(prev => prev.filter(x => x.id !== id)))}
                        onUpdatePart={(p) => setParts(prev => prev.map(x => x.id === p.id ? p : x))}
                    />
                );
            case AppMode.ScriptLibrary:
                return (
                    <ScriptLibraryView 
                        scripts={scripts} tools={tools} parts={parts}
                        onSaveScript={(s) => setScripts(prev => prev.map(x => x.id === s.id ? s : x))}
                        onDeleteScript={(id) => setScripts(prev => prev.filter(x => x.id !== id))}
                        onCreatePart={(p) => setParts(prev => [...prev, p])}
                        onBatchProcess={(p, sp) => { /* Logic */ }}
                    />
                );
            case AppMode.ToolLibrary:
                return <ToolLibraryView tools={tools} onSaveTool={(t) => setTools(prev => [...prev, t])} onDeleteTool={(id) => setTools(prev => prev.filter(x => x.id !== id))} />;
            case AppMode.TurretSetup:
                return <TurretSetupView tools={tools} setTools={setTools} layouts={turretLayouts} setLayouts={setTurretLayouts} />;
            case AppMode.MachineSetup:
                return <MachineSetupView settings={machineSettings} onUpdate={setMachineSettings} />;
            default:
                return <div className="flex-1 flex items-center justify-center">Режим в разработке</div>;
        }
    };

    return (
        <div className="flex flex-col h-full font-sans relative overflow-hidden bg-gray-800">
            <Header 
                mode={mode} setMode={setMode} 
                onGenerateGCode={() => {}} onOptimizePath={() => {}}
                onOpenTurretConfig={() => setMode(AppMode.TurretSetup)}
            />
            {renderModeContent()}
            <ToastContainer toasts={toasts} removeToast={removeToast} />
            <ConfirmationModal state={confirmationState} onCancel={closeConfirmation} />
        </div>
    );
};

export default App;

import React from 'react';
import { Part, Tool, Point, ManualPunchMode, PlacementReference, PlacementSide, SnapMode } from '../../types';
import { ToolSvg } from '../common/ToolDisplay';
import { ProcessedGeometry, findSnapPoint } from '../../services/geometry';
import { useGhostPreview } from '../../hooks/useGhostPreview';

interface PartEditorCanvasProps {
    activePart: Part;
    processedGeometry: ProcessedGeometry | null;
    tools: Tool[];
    mousePos: Point | null;

    // Manual Punching State
    manualPunchMode: ManualPunchMode;
    punchCreationStep: number;
    punchCreationPoints: Point[];
    selectedToolId: string | null;
    selectedPunchId: string | null;

    placementReference: PlacementReference;
    placementSide: PlacementSide;
    punchOrientation: number;
    punchOffset: number;
    snapMode: SnapMode;
    nibbleSettings: any;

    // Teach Mode
    teachMode: boolean;
    selectedSegmentIds: number[];
    selectedTeachPunchIds: string[];
    // FIX: Added missing onTeachBulkSelect prop to match usages in parent views.
    onTeachBulkSelect?: (segmentIndices: number[], punchIds: string[], add: boolean) => void;
    // FIX: Updated onSelectPunch to accept string | null to match state setters (string | null).
    onSelectPunch: (id: string | null) => void;
}

export const PartEditorCanvas: React.FC<PartEditorCanvasProps> = ({
    activePart, processedGeometry, tools, mousePos,
    manualPunchMode, punchCreationStep, punchCreationPoints, selectedToolId, selectedPunchId,
    placementReference, placementSide, punchOrientation, punchOffset, snapMode, nibbleSettings,
    teachMode, selectedSegmentIds, selectedTeachPunchIds, onTeachBulkSelect, onSelectPunch
}) => {

    const selectedTool = tools.find(t => t.id === selectedToolId);

    const { ghostPunches, ghostLine, snapPoint } = useGhostPreview({
        mousePos, activePart, processedGeometry, selectedTool, manualPunchMode, snapMode, 
        punchOrientation, punchOffset, nibbleSettings, punchCreationStep, teachMode
    });

    const getArcPath = (seg: any): string => {
        if (!seg.radius || !seg.center) return `M ${seg.p1.x} ${seg.p1.y} L ${seg.p2.x} ${seg.p2.y}`;
        const r = seg.radius;
        const p1 = seg.p1;
        const p2 = seg.p2;

        let largeArc = 0;
        const sweep = 1; // Default CCW in DXF->SVG coords

        // Use original entity to get accurate flags
        if (seg.originalEntity && seg.originalEntity.type === 'ARC') {
            const arc = seg.originalEntity;
            let diff = arc.endAngle - arc.startAngle;
            if (diff < 0) diff += 360;
            largeArc = diff > 180 ? 1 : 0;
        }

        return `M ${p1.x} ${p1.y} A ${r} ${r} 0 ${largeArc} ${sweep} ${p2.x} ${p2.y}`;
    };

    const renderTeachModeHighlights = () => {
        if (!teachMode || !processedGeometry) return null;
        return processedGeometry.segments.map((seg, idx) => {
            const isSelected = selectedSegmentIds.includes(idx);
            let pathD = seg.type === 'line' ? `M ${seg.p1.x} ${seg.p1.y} L ${seg.p2.x} ${seg.p2.y}` : getArcPath(seg);

            if (isSelected) {
                // Выбранный сегмент: Непрозрачный, два слоя
                return (
                    <g key={idx} className="cursor-pointer" onClick={(e) => e.stopPropagation()}>
                        {/* Hit area */}
                        <path d={pathD} stroke="transparent" strokeWidth="15" fill="none" vectorEffect="non-scaling-stroke"/>

                        {/* Bottom Layer: Saturated Green (#22c55e), Thick */}
                        <path d={pathD} stroke="#22c55e" strokeWidth="6" fill="none" vectorEffect="non-scaling-stroke" strokeLinecap="round" opacity="1" />

                        {/* Top Layer: Black (#000000), Medium */}
                        <path d={pathD} stroke="#000000" strokeWidth="2.5" fill="none" vectorEffect="non-scaling-stroke" strokeLinecap="round" />
                    </g>
                );
            }

            // Unselected segments - hover effect
            return (
                <g key={idx} className="cursor-pointer group" onClick={(e) => e.stopPropagation()}>
                    <path d={pathD} stroke="transparent" strokeWidth="10" fill="none" vectorEffect="non-scaling-stroke"/>

                    {/* Hover: Bright Blue (#3b82f6) */}
                    <path d={pathD} stroke="transparent" strokeWidth="4" fill="none" vectorEffect="non-scaling-stroke" className="group-hover:stroke-[#3b82f6] transition-colors duration-75" strokeLinecap="round"/>
                </g>
            );
        });
    };

    const renderGhostGeometry = () => {
        if (!mousePos) return null;
        // Destruct line start to mouse
        if (manualPunchMode === ManualPunchMode.Destruct && punchCreationStep > 0) {
            const startPoint = punchCreationPoints[0];
            const finalPoint = findSnapPoint(mousePos, processedGeometry, snapMode)?.point ?? mousePos;
             return <line x1={startPoint.x} y1={startPoint.y} x2={finalPoint.x} y2={finalPoint.y} stroke="yellow" strokeWidth="1" vectorEffect="non-scaling-stroke" strokeDasharray="4 2" />
        }
        return null;
    };

    return (
        <g>
            <path d={activePart.geometry.path} fill="rgba(31, 41, 55, 0.5)" stroke="#63b3ed" strokeWidth="2" vectorEffect="non-scaling-stroke" />

            {teachMode && renderTeachModeHighlights()}

            {activePart.punches.map(punch => {
                const tool = tools.find(t => t.id === punch.toolId);
                if(!tool) return null;

                const isSelected = teachMode ? selectedTeachPunchIds.includes(punch.id) : punch.id === selectedPunchId;
                const isGrouped = !!punch.lineId;

                // Tool Selection Style
                let strokeColor = "cyan";
                let strokeOp = 1.0;

                if (isSelected) {
                    if (teachMode) {
                        strokeColor = "#ec4899"; // Pink-500
                        strokeOp = 0.5; // Semi-transparent
                    } else {
                        strokeColor = "cyan";
                        strokeOp = 1.0;
                    }
                }

                return (
                <g key={punch.id} transform={`translate(${punch.x}, ${punch.y}) rotate(${punch.rotation})`} onClick={(e) => { e.stopPropagation(); onSelectPunch(punch.id); }} className="cursor-pointer">
                    {/* Selection Box (Bottom Layer) */}
                    {isSelected && (
                        <rect 
                            x={-tool.width/2-2} 
                            y={-tool.height/2-2} 
                            width={tool.width+4} 
                            height={tool.height+4} 
                            fill="none" 
                            stroke={strokeColor} 
                            strokeWidth="2" 
                            strokeOpacity={strokeOp}
                            vectorEffect="non-scaling-stroke" 
                        />
                    )}

                    {/* Center Cross */}
                    <path d="M -2 0 L 2 0 M 0 -2 L 0 2" stroke={isSelected ? strokeColor : "red"} strokeWidth="0.5" strokeOpacity={strokeOp} vectorEffect="non-scaling-stroke"/>

                    {/* Tool Body */}
                    <g opacity={isSelected ? 1 : 0.7}><ToolSvg tool={tool} /></g>

                    {/* Group Indicator */}
                    {isGrouped && isSelected && !teachMode && <circle r="2" fill="yellow" cy="-5"/>}
                </g>
                )
            })}

            {renderGhostGeometry()}

            {/* Render Ghost Tools from Hook */}
            {selectedTool && ghostPunches.length > 0 && (
                <g opacity="0.6" style={{ pointerEvents: 'none' }}>
                    {ghostPunches.map((p, idx) => (
                        <g key={idx} transform={`translate(${p.x}, ${p.y}) rotate(${p.rotation})`}>
                            <ToolSvg tool={selectedTool} />
                        </g>
                    ))}
                    {ghostLine && (
                        <line x1={ghostLine.x1} y1={ghostLine.y1} x2={ghostLine.x2} y2={ghostLine.y2} stroke="cyan" strokeWidth="2" vectorEffect="non-scaling-stroke" strokeDasharray="5 5"/>
                    )}
                    {snapPoint && (
                        <circle cx={snapPoint.x} cy={snapPoint.y} r="5" fill="none" stroke="cyan" strokeWidth="2" vectorEffect="non-scaling-stroke" />
                    )}
                </g>
            )}
        </g>
    );
};
